package main

import (
	"context"
	"fmt"
	"io"
	"os"
	"strings"
	"time"

	plugin "github.com/SemRels/provider-gitlab/internal/plugin"
)

const pluginSchemaVersion = 1

const commandTimeout = 30 * time.Second

func main() {
	os.Exit(run(context.Background(), os.Stdout, os.Stderr, os.LookupEnv))
}

func run(parent context.Context, stdout, stderr io.Writer, lookupEnv func(string) (string, bool)) int {
	_, _ = fmt.Fprintf(stderr, "plugin_schema_version=%d\n", pluginSchemaVersion)
	cfg := plugin.ConfigFromLookupEnv(lookupEnv)
	if err := cfg.Validate(); err != nil {
		_, _ = fmt.Fprintf(stderr, "provider-gitlab: %v\n", err)
		return 1
	}

	if isDryRun(lookupEnv) {
		if strings.TrimSpace(cfg.Token) == "" {
			_, _ = fmt.Fprintln(stderr, "[dry-run] provider-gitlab: would need GITLAB_TOKEN (or SEMREL_PLUGIN_TOKEN / CI_JOB_TOKEN) to create release")
		}
		_, _ = fmt.Fprintf(stderr, "[dry-run] provider-gitlab: would create release %s for project %s\n", cfg.TagName, cfg.ProjectID)
		_, _ = fmt.Fprintf(stdout, "[dry-run] would create GitLab release %s for project %s\n", cfg.TagName, cfg.ProjectID)
		_, _ = fmt.Fprintf(stdout, "tag: %s\ntitle: %s\ntarget: %s/api/v4/projects/%s/releases\n", cfg.TagName, cfg.Name, strings.TrimRight(cfg.BaseURL, "/"), cfg.ProjectID)
		if assets := strings.TrimSpace(valueFromEnv(lookupEnv, "SEMREL_PLUGIN_ASSETS", "")); assets != "" {
			_, _ = fmt.Fprintf(stdout, "assets: %s\n", assets)
		}
		if cfg.Description != "" {
			_, _ = fmt.Fprintf(stdout, "notes:\n%s\n", cfg.Description)
		}
		return 0
	}

	ctx, cancel := context.WithTimeout(parent, commandTimeout)
	defer cancel()

	creator := plugin.New(cfg)
	release, err := creator.CreateRelease(ctx)
	if err != nil {
		_, _ = fmt.Fprintf(stderr, "provider-gitlab: %v\n", err)
		return 1
	}
	if err := creator.CommentOnMergeRequests(ctx, cfg, release); err != nil {
		_, _ = fmt.Fprintf(stderr, "provider-gitlab: %v\n", err)
		return 1
	}

	_, _ = fmt.Fprintf(stdout, "created GitLab release %s\n", release.TagName)
	return 0
}

func isDryRun(lookupEnv func(string) (string, bool)) bool {
	return strings.EqualFold(strings.TrimSpace(valueFromEnv(lookupEnv, "SEMREL_DRY_RUN", "")), "true")
}

func valueFromEnv(lookupEnv func(string) (string, bool), key, fallback string) string {
	value, ok := lookupEnv(key)
	if !ok {
		return fallback
	}
	return value
}
